package local.ziweixingyu.rebuild;
import android.widget.*;
import android.text.InputType;
import java.util.*;
import org.json.*;

final class FlowController {
 final MainActivity host;int mode=0,age=1,month=1;JSONObject data,decadal,annual;String source="";boolean lines=true;EditText ageInput;TextView heading,details,period;MainActivity.ChartView canvas;final Button[] modeButtons=new Button[4];
 LinearLayout months;Spinner monthInput;
 FlowController(MainActivity host){this.host=host;}
 void reset(JSONObject chart){mode=0;month=1;data=null;decadal=null;annual=null;source="";try{age=Math.max(1,Math.min(120,Calendar.getInstance(TimeZone.getTimeZone("GMT+8")).get(Calendar.YEAR)-Integer.parseInt(chart.getJSONObject("其他信息").getString("农历年"))+1));}catch(Exception e){age=1;}}
 void attach(LinearLayout content,MainActivity.ChartView view){canvas=view;LinearLayout box=host.column();box.setPadding(host.dp(8),host.dp(4),host.dp(8),host.dp(8));content.addView(box);
  LinearLayout modes=host.row();String[] names={"本命","大限","流年","流月"};for(int i=0;i<4;i++){final int chosen=i;modeButtons[i]=host.button(names[i],()->select(chosen));modes.addView(modeButtons[i],new LinearLayout.LayoutParams(0,host.dp(44),1));}box.addView(modes);
  LinearLayout years=host.row();years.addView(host.text("虚岁",14,MainActivity.INK),new LinearLayout.LayoutParams(host.dp(38),host.dp(44)));years.addView(host.button("−",()->step(-1)),new LinearLayout.LayoutParams(host.dp(46),host.dp(44)));
  ageInput=host.edit(String.valueOf(age),"1—120",InputType.TYPE_CLASS_NUMBER);years.addView(ageInput,new LinearLayout.LayoutParams(0,host.dp(44),1));years.addView(host.button("+",()->step(1)),new LinearLayout.LayoutParams(host.dp(46),host.dp(44)));years.addView(host.button("应用",()->apply()),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));box.addView(years);
  months=host.row();months.addView(host.text("农历月",14,MainActivity.INK),new LinearLayout.LayoutParams(host.dp(64),host.dp(44)));months.addView(host.button("上月",()->changeMonth(-1)),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));monthInput=new Spinner(host);ArrayAdapter<String> adapter=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,MonthState.MONTHS);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);monthInput.setAdapter(adapter);monthInput.setSelection(month-1);months.addView(monthInput,new LinearLayout.LayoutParams(0,host.dp(44),1));months.addView(host.button("下月",()->changeMonth(1)),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));box.addView(months);monthInput.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,android.view.View v,int pos,long id){if(month!=pos+1){month=pos+1;clearSource();refresh();}}});
  LinearLayout options=host.row();CheckBox showLines=new CheckBox(host);showLines.setText("四化连线");showLines.setTextSize(14);showLines.setChecked(lines);showLines.setOnCheckedChangeListener((b,on)->{lines=on;canvas.invalidate();});options.addView(showLines,new LinearLayout.LayoutParams(0,host.dp(44),1));options.addView(host.button("回到命宫",()->{clearSource();refresh();}),new LinearLayout.LayoutParams(0,host.dp(44),1));box.addView(options);
  heading=host.text("",15,MainActivity.TEAL);box.addView(heading);period=host.text("",13,MainActivity.TEAL);box.addView(period);details=host.text("",14,MainActivity.INK);details.setTextIsSelectable(true);box.addView(details);refresh();
 }
 void clearSource(){source="";if(canvas!=null)canvas.selected=-1;}
 void select(int selected){mode=selected;clearSource();refresh();}
 void chooseSource(String branch){if(data==null||data.optJSONObject("palaces").length()==0)return;source=branch;refresh();}
 void cycle(){select((mode+1)%4);}
 void changeMonth(int direction){try{month=MonthState.step(month,direction);monthInput.setSelection(month-1);clearSource();refresh();}catch(Exception e){host.message("月份未切换",e.getMessage());}}
 void apply(){try{int next=Integer.parseInt(ageInput.getText().toString());if(next<1||next>120)throw new Exception();age=next;clearSource();ageInput.setError(null);((android.view.inputmethod.InputMethodManager)host.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(ageInput.getWindowToken(),0);refresh();}catch(Exception e){ageInput.setError("请输入1至120的虚岁");}}
 void step(int direction){try{age=FlowState.step(host.chart,mode!=1,age,direction);clearSource();ageInput.setText(String.valueOf(age));ageInput.setError(null);refresh();}catch(Exception e){host.message("暂时无法切换",e.getMessage());}}
 void refresh(){for(int i=0;i<4;i++){modeButtons[i].setSelected(i==mode);modeButtons[i].setTextColor(i==mode?android.graphics.Color.WHITE:MainActivity.INK);modeButtons[i].setBackgroundTintList(android.content.res.ColorStateList.valueOf(i==mode?MainActivity.TEAL:0xffeeeeee));}try{data=mode==0?null:mode==3?MonthState.describe(host.chart,age,month):FlowState.describe(host.chart,mode==2,age);decadal=mode>=2?FlowState.describe(host.chart,false,age):null;annual=mode==3?FlowState.describe(host.chart,true,age):null;months.setVisibility(mode==3?android.view.View.VISIBLE:android.view.View.GONE);if(data!=null&&!source.isEmpty())data=FlowState.selectSource(host.chart,data,source);heading.setText(data==null?"本命命盘":data.getString("title"));period.setText((annual==null?"":annual.getString("title")+"\n")+(decadal==null?"":decadal.getString("title"))+(mode==3?"\n按月序查看，暂不区分当年闰月":""));period.setVisibility(decadal==null?android.view.View.GONE:android.view.View.VISIBLE);details.setText(data==null?"点击圆盘可切换本命、大限、流年。":summaryBody());canvas.setContentDescription("紫微十二宫命盘 · "+heading.getText()+(decadal==null?"":" · 同时叠加"+decadal.optString("title"))+(data==null?"":" · 四化来源"+data.optString("source",data.optString("anchor"))));canvas.invalidate();}catch(Exception e){data=null;decadal=null;annual=null;heading.setText("流运未生成");period.setVisibility(android.view.View.GONE);details.setText(e.getMessage());canvas.invalidate();}}
 String summaryBody(){if(data==null)return "";StringBuilder out=new StringBuilder(prefix()+data.optString("sourceLabel","命")+"在"+data.optString("source",data.optString("anchor"))+" · "+data.optString("stem")+"干四化\n");JSONObject t=data.optJSONObject("transforms");if(t.length()==0)return "尚未进入首限，可调整虚岁或查看流年。";
  for(String mark:new String[]{"禄","权","科","忌"})for(Iterator<String> it=t.keys();it.hasNext();){String star=it.next();JSONObject v=t.optJSONObject(star);if(mark.equals(v.optString("化")))out.append(star).append("化").append(mark).append(" → ").append(v.optString("支")).append(v.optString("流宫")).append("宫").append(v.has("力度")?"（"+v.optInt("力度")+"%）":"（力度未确认）").append('\n');}return out.toString().trim();
 }
 String summary(){return data==null?"":"\n\n"+data.optString("title")+"\n"+(annual==null?"":"同时叠加："+annual.optString("title")+"\n")+(decadal==null?"":"同时叠加："+decadal.optString("title")+"\n")+summaryBody()+monthSummary();}
 String overlay(String branch){return data==null?"":data.optJSONObject("palaces").optString(branch,"");}
 String prefix(){return mode==1?"限":mode==3?"月":"年";}
 String monthSummary(){if(mode!=3||data==null)return "";StringBuilder text=new StringBuilder("\n月份分布（不区分当年闰月）\n");JSONObject map=data.optJSONObject("monthMap");for(int m=1;m<=12;m++)for(int i=0;i<12;i++){String b=FlowState.BRANCH.substring(i,i+1);JSONObject item=map.optJSONObject(b);if(item.optInt("month")==m)text.append(item.optString("name")).append(item.optString("stem")).append("：").append(b).append("宫\n");}return text.toString().trim().isEmpty()?"":"\n"+text.toString().trim();}
}
